const norm = (value) => String(value ?? "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/&/g, " and ")
  .replace(/[_/]+/g, " ")
  .replace(/[^a-z0-9]+/g, " ")
  .trim()
  .replace(/\s+/g, " ");

let places;
const placeIndex = () => {
  if (places) return places;
  const map = new Map();
  const add = (name, zone) => {
    const key = norm(name);
    if (key.length < 2 || skip.has(key)) return;
    const list = map.get(key);
    if (!list) map.set(key, [zone]);
    else if (!list.includes(zone)) list.push(zone);
  };
  const addZone = (zone) => {
    if (!zone || zone.startsWith("Etc/")) return;
    add(zone, zone);
    const parts = zone.split("/");
    add(parts[parts.length - 1].replace(/_/g, " "), zone);
    if (parts.length > 2) add(parts[parts.length - 2].replace(/_/g, " "), zone);
  };
  for (const [key, zones] of Object.entries(indexData)) for (const zone of zones) add(key, zone);
  try { for (const zone of Intl.supportedValuesOf("timeZone")) addZone(zone); } catch (e) {}
  places = map;
  return map;
};

const lookup = (raw) => {
  const map = placeIndex();
  const key = norm(raw);
  const zones = map.get(key) || map.get(key.replace(/ (state|county|province|territory|region)$/, ""));
  return zones && zones.length ? zones : null;
};

const wall = (date, timeZone) => {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone, hourCycle: "h23", year: "numeric", month: "numeric", day: "numeric",
    hour: "numeric", minute: "numeric", second: "numeric",
  }).formatToParts(date);
  const n = (type) => Number((parts.find((part) => part.type === type) || {}).value);
  const hour = n("hour");
  return { y: n("year"), m: n("month"), d: n("day"), h: hour === 24 ? 0 : hour, i: n("minute") };
};

const offsetAt = (ms, timeZone) => {
  const part = wall(new Date(ms), timeZone);
  return Date.UTC(part.y, part.m - 1, part.d, part.h, part.i) - ms;
};

const choose = (zones, ms) => {
  const found = new Map();
  for (const zone of zones) {
    const off = offsetAt(ms, zone);
    if (!found.has(off)) found.set(off, zone);
  }
  return found.size === 1 ? found.values().next().value : null;
};

const cityName = (zone) => zone.split("/").pop().replace(/_/g, " ").replace(/\b[a-z]/g, (letter) => letter.toUpperCase());

const hint = (zones, ms) => {
  const names = [];
  const seenOff = new Set();
  const seenName = new Set();
  for (const zone of zones) {
    if (zone.startsWith("Etc/")) continue;
    const name = cityName(zone);
    const off = offsetAt(ms, zone);
    if (seenOff.has(off) || seenName.has(name)) continue;
    seenOff.add(off);
    seenName.add(name);
    names.push(name);
    if (names.length === 5) break;
  }
  if (names.length < 2) return names[0] || "a city";
  return `${names.slice(0, -1).join(", ")} or ${names[names.length - 1]}`;
};

const label = (raw, zone) => {
  const text = String(raw ?? "").trim().replace(/\s+/g, " ");
  if (text.includes("/") && zone) return zone;
  return text.split(" ").map((word) => {
    const low = word.toLowerCase();
    if (initials.has(low)) return low.toUpperCase();
    return low.charAt(0).toUpperCase() + low.slice(1);
  }).join(" ");
};

const resolve = (raw, ms) => {
  if (hereWord.has(norm(raw))) return { zone: localZone(), name: "here" };
  const zones = lookup(raw);
  if (!zones) throw new Error(`${label(raw)} is not a place I know.`);
  const zone = zones.length === 1 ? zones[0] : choose(zones, ms);
  if (!zone) throw new Error(`${label(raw)} has several time zones. Try ${hint(zones, ms)}.`);
  return { zone, name: label(raw, zone) };
};

const localZone = () => {
  try { return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"; }
  catch (e) { return "UTC"; }
};

const matches = (part, y, m, d, h, min) => part.y === y && part.m === m && part.d === d && part.h === h && part.i === min;

const instants = (y, m, d, h, min, timeZone) => {
  const naive = Date.UTC(y, m - 1, d, h, min);
  let guess = naive - offsetAt(naive, timeZone);
  guess = naive - offsetAt(guess, timeZone);
  const hits = [];
  for (const step of [-120, -90, -60, -30, 0, 30, 60, 90, 120]) {
    const at = guess + step * 60000;
    if (matches(wall(new Date(at), timeZone), y, m, d, h, min) && !hits.includes(at)) hits.push(at);
  }
  hits.sort((a, b) => a - b);
  return hits;
};

const zoneText = (ms, timeZone) => {
  const read = (style) => {
    const parts = new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: style }).formatToParts(new Date(ms));
    return (parts.find((part) => part.type === "timeZoneName") || {}).value || "";
  };
  const short = read("short");
  return /^[A-Za-z]{2,5}$/.test(short) ? short : (read("shortOffset") || short);
};

const pad = (n) => String(n).padStart(2, "0");

const face = (hour, minute, twentyFour) => {
  const mm = pad(minute);
  if (twentyFour) return `${pad(hour)}:${mm}`;
  return `${hour % 12 || 12}:${mm}${hour < 12 ? "am" : "pm"}`;
};

const shown = (ms, timeZone, twentyFour) => {
  const part = wall(new Date(ms), timeZone);
  return { face: face(part.h, part.i, twentyFour), abbr: zoneText(ms, timeZone) };
};

const clockText = (clock, zoneOn) => zoneOn && clock.abbr ? `${clock.face} ${clock.abbr}` : clock.face;

const onDate = (text) => {
  const match = /\bon\s+/i.exec(text);
  if (!match) return null;
  const from = match.index + match[0].length;
  const words = text.slice(from).split(" ");
  let best = null, invalid = null;
  for (let count = 1; count <= Math.min(words.length, 12); count++) {
    const phrase = words.slice(0, count).join(" ");
    try { best = { phrase, iso: ghost.date(phrase), end: from + phrase.length }; }
    catch (error) {
      const message = String((error && error.message) || error);
      if (message.includes("not a real day")) invalid = message;
    }
  }
  if (best) return { start: match.index, end: best.end, iso: best.iso };
  if (invalid && /^\d{4}-\d{2}-\d{2}$|^\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{4}$/.test(words[0] || "")) throw new Error(invalid);
  return null;
};

const lastJoin = (body) => {
  const re = /(?:^|\s+)(?:in|to)\s+/gi;
  let match, last;
  while ((match = re.exec(body))) last = match;
  return last;
};

const parse = (source) => {
  let text = String(source ?? "").trim().replace(/\s+/g, " ");
  if (!text) throw new Error("type a place, such as in Dallas, or a time such as 5pm in Sydney.");
  let year, month, day, dated = false;
  const on = onDate(text);
  if (on) {
    const parts = on.iso.split("-");
    year = Number(parts[0]); month = Number(parts[1]); day = Number(parts[2]); dated = true;
    if (year < 1970 || year > 2100) throw new Error("use a date from 1970 through 2100.");
    text = `${text.slice(0, on.start)} ${text.slice(on.end)}`.trim().replace(/\s+/g, " ");
    if (!text) throw new Error("add a time, such as 5pm on 2026-03-08 in Dallas.");
  }
  const now = /^(?:in|to)\s+(.+)$/i.exec(text);
  if (now) {
    if (dated) throw new Error("add a time, such as 5pm on 2026-03-08 in Dallas.");
    return { now: true, target: now[1] };
  }
  const time = /^(\d{1,2})(?::([0-5]\d))?\s*(am|pm)?\b\s*/i.exec(text);
  if (!time) {
    if (dated) throw new Error("add a time, such as 5pm on 2026-03-08 in Dallas.");
    if (/(?:^|\s)(?:in|to)\s/i.test(text)) throw new Error("add a time, such as 2pm London in San Francisco.");
    return { now: true, target: text };
  }
  let hour = Number(time[1]);
  const minute = time[2] ? Number(time[2]) : 0;
  const ap = (time[3] || "").toLowerCase();
  if (ap) {
    if (hour < 1 || hour > 12) throw new Error("an hour with am or pm is from 1 to 12.");
    hour = ap === "am" ? (hour === 12 ? 0 : hour) : (hour === 12 ? 12 : hour + 12);
  } else if (hour > 23) throw new Error("an hour is from 0 to 23, or use am and pm.");
  const body = text.slice(time[0].length).trim();
  const spot = lastJoin(body);
  if (!spot) throw new Error("say where, such as 5pm in Sydney or 2pm London in San Francisco.");
  const sourcePlace = body.slice(0, spot.index).trim().replace(/^(?:in|to)\s+/i, "");
  const target = body.slice(spot.index + spot[0].length).trim();
  if (!target) throw new Error("say where, such as 5pm in Sydney.");
  return { hour, minute, twentyFour: !ap, source: sourcePlace, target, year, month, day };
};

const today = (timeZone, now) => wall(now, timeZone);

const convert = (source, zoneOn) => {
  const query = parse(source);
  const now = new Date();
  if (query.now) {
    const place = resolve(query.target, now.getTime());
    return clockText(shown(now.getTime(), place.zone, false), zoneOn);
  }
  const probe = Date.UTC(query.year || today(localZone(), now).y, (query.month || today(localZone(), now).m) - 1, query.day || today(localZone(), now).d, query.hour, query.minute);
  const target = resolve(query.target, probe);
  const sourcePlace = query.source ? resolve(query.source, probe) : { zone: localZone(), name: "here" };
  const day = query.year ? { y: query.year, m: query.month, d: query.day } : today(sourcePlace.zone, now);
  const hits = instants(day.y, day.m, day.d, query.hour, query.minute, sourcePlace.zone);
  if (!hits.length) {
    throw new Error(`${face(query.hour, query.minute, query.twentyFour)} does not happen in ${sourcePlace.name} on ${day.y}-${pad(day.m)}-${pad(day.d)}; the clocks spring forward.`);
  }
  const note = hits.length > 1 ? " (the earlier of two)" : "";
  return `${clockText(shown(hits[0], target.zone, query.twentyFour), zoneOn)}${note}`;
};

